param(
  [switch]$WithHelpTags
)

$ErrorActionPreference = 'Stop'

if (-not (Get-Command nvim -ErrorAction SilentlyContinue)) {
  throw "Neovim ('nvim') is required to run this smoke check."
}

$nvimArgs = @(
  '--headless',
  '-u',
  'NONE',
  '+set rtp+=.',
  '+runtime plugin/gh-pr.lua',
  '+lua require("gh-pr").setup({ ui = { use_neotree = false, telescope_fallback = false }, diff_view = { prefetch = { enabled = true, concurrency = 2, text_extensions = { "lua", ".md" } }, non_text = { enabled = true, auto_preview = true, show_metadata = true } } })',
  '+lua local cfg = require("gh-pr.config").get(); local prefetch = cfg.diff_view.prefetch or {}; local comments_panel = cfg.diff_view.comments_panel or {}; local non_text = cfg.diff_view.non_text or {}; local pr_service = require("gh-pr.pr_service"); local virtual_files = require("gh-pr.virtual_files"); local actions = require("gh-pr.actions"); local ok_annotations = pcall(require, "gh-pr.check_annotations"); local ok_security_annotations = pcall(require, "gh-pr.security_annotations"); local ok_security_section = pcall(require, "gh-pr.neotree.review_sections.security"); assert(vim.fn.exists(":GhPrOpen") == 2, "Missing :GhPrOpen command"); assert(vim.fn.exists(":GhPrReviewRefresh") == 2, "Missing :GhPrReviewRefresh command"); assert(vim.fn.exists(":GhPRReviewRefresh") == 2, "Missing :GhPRReviewRefresh alias"); assert(vim.fn.maparg("<Plug>(gh-pr-open)", "n") ~= "", "Missing <Plug>(gh-pr-open)"); assert(vim.fn.maparg("<Plug>(gh-pr-review-refresh)", "n") ~= "", "Missing <Plug>(gh-pr-review-refresh)"); assert(prefetch.enabled == true, "Missing diff_view.prefetch.enabled"); assert(prefetch.concurrency == 2, "Missing diff_view.prefetch.concurrency"); assert(prefetch.text_extensions[1] == "lua" and prefetch.text_extensions[2] == "md", "Missing diff_view.prefetch.text_extensions"); assert(comments_panel.position == "bottom", "Missing diff_view.comments_panel.position default"); assert(non_text.enabled == true, "Missing diff_view.non_text.enabled"); assert(non_text.auto_preview == true, "Missing diff_view.non_text.auto_preview"); assert(non_text.show_metadata == true, "Missing diff_view.non_text.show_metadata"); assert(type(virtual_files.classify_file) == "function", "Missing virtual_files.classify_file"); assert(virtual_files.classify_file({ path = "a.png", patch = "" }) == "image", "Expected image classification"); assert(virtual_files.classify_file({ path = "a.zip", patch = "" }) == "asset", "Expected asset classification"); assert(virtual_files.classify_file({ path = "a.lua", patch = "" }) == "text", "Expected text classification"); assert(type(actions.run_non_text_default_action) == "function", "Missing actions.run_non_text_default_action"); assert(type(actions.open_non_text_actions_menu) == "function", "Missing actions.open_non_text_actions_menu"); assert(type(actions.run_non_text_action_at_cursor) == "function", "Missing actions.run_non_text_action_at_cursor"); assert(type(actions.open_security_alert_location) == "function", "Missing actions.open_security_alert_location"); assert(type(pr_service.reply_to_review_thread) == "function", "Missing pr_service.reply_to_review_thread"); assert(type(pr_service.resolve_review_thread) == "function", "Missing pr_service.resolve_review_thread"); assert(type(pr_service.unresolve_review_thread) == "function", "Missing pr_service.unresolve_review_thread"); assert(type(pr_service.update_review_comment) == "function", "Missing pr_service.update_review_comment"); assert(type(pr_service.delete_review_comment) == "function", "Missing pr_service.delete_review_comment"); assert(type(pr_service.set_review_comment_reaction) == "function", "Missing pr_service.set_review_comment_reaction"); assert(type(pr_service.fetch_review_threads_with_pending) == "function", "Missing pr_service.fetch_review_threads_with_pending"); assert(type(pr_service.fetch_review_threads_with_pending_async) == "function", "Missing pr_service.fetch_review_threads_with_pending_async"); assert(type(pr_service.fetch_viewed_files) == "function", "Missing pr_service.fetch_viewed_files"); assert(type(pr_service.fetch_viewed_files_async) == "function", "Missing pr_service.fetch_viewed_files_async"); assert(type(pr_service.set_files_viewed) == "function", "Missing pr_service.set_files_viewed"); assert(type(pr_service.fetch_check_annotations) == "function", "Missing pr_service.fetch_check_annotations"); assert(type(pr_service.fetch_check_annotations_async) == "function", "Missing pr_service.fetch_check_annotations_async"); assert(type(pr_service.fetch_code_scanning_alerts) == "function", "Missing pr_service.fetch_code_scanning_alerts"); assert(type(pr_service.fetch_code_scanning_alerts_async) == "function", "Missing pr_service.fetch_code_scanning_alerts_async"); assert(type(pr_service.fetch_dependency_review) == "function", "Missing pr_service.fetch_dependency_review"); assert(type(pr_service.fetch_dependency_review_async) == "function", "Missing pr_service.fetch_dependency_review_async"); assert(ok_annotations == true, "Missing gh-pr.check_annotations module"); assert(ok_security_annotations == true, "Missing gh-pr.security_annotations module"); assert(ok_security_section == true, "Missing gh-pr.neotree.review_sections.security module"); local ok, health = pcall(require, "gh-pr.health"); assert(ok and type(health.check) == "function", "Missing gh-pr health check entrypoint")',
  '+lua local popup = require("gh-pr.comment_popup"); local origin = vim.api.nvim_get_current_buf(); local ok = select(1, popup.open({ origin_bufnr = origin, tag = "thread", title = "Smoke", items = { { id = "c1", author = "user", body = "body", meta = { thread_id = "t1", viewer_did_author = true, reaction_groups = {} } } }, actions = { reply = function() end, quote = function() end, toggle_thread = function() end, edit = function() end, delete = function() end, add_reaction = function() end, remove_reaction = function() end }, enter = true, position = "editor" })); assert(ok == true, "Comment popup should open"); assert(vim.fn.maparg("r", "n", false, true).desc == "Reply to selected PR thread", "Missing popup reply mapping"); assert(vim.fn.maparg("R", "n", false, true).desc == "Quote-reply to selected PR thread", "Missing popup quote mapping"); assert(vim.fn.maparg("x", "n", false, true).desc == "Resolve or unresolve selected PR thread", "Missing popup resolve mapping"); assert(vim.fn.maparg("e", "n", false, true).desc == "Edit selected PR comment", "Missing popup edit mapping"); assert(vim.fn.maparg("D", "n", false, true).desc == "Delete selected PR comment", "Missing popup delete mapping"); assert(vim.fn.maparg("+", "n", false, true).desc == "Add reaction to selected PR comment", "Missing popup reaction-add mapping"); assert(vim.fn.maparg("-", "n", false, true).desc == "Remove reaction from selected PR comment", "Missing popup reaction-remove mapping"); popup.close_for_origin(origin, "thread")',
  '+lua local drafts = require("gh-pr.neotree.review_sections.drafts"); local nodes = drafts.build_nodes({ number = 42 }, { pending_review_loaded = true, pending_review_comments = { { id = "c1", thread_id = "t1", path = "lua/gh-pr/actions.lua", thread_path = "lua/gh-pr/actions.lua", line = 10, original_line = 10, thread_line = 10, thread_original_line = 10, body = "draft body", author = "reviewer", created_at = "2026-03-07T00:00:00Z", state = "PENDING" } } }); assert(type(nodes) == "table" and nodes[1] and nodes[1].type == "comment_file", "Drafts section should group by file"); assert(type(nodes[1].children) == "table" and nodes[1].children[1] and nodes[1].children[1].extra.kind == "comment_thread", "Drafts section should group by thread"); assert(type(nodes[1].children[1].children) == "table" and nodes[1].children[1].children[1] and nodes[1].children[1].children[1].extra.kind == "comment_thread_item", "Drafts section should expose draft comments as navigable items")',
  '+lua local actions = require("gh-pr.actions"); local called; local original = actions.open_thread_comment_evolution_diff; actions.open_thread_comment_evolution_diff = function(payload, opts) called = { payload = payload, opts = opts }; return true end; actions.open_overview_thread_workspace({ pr_number = 123, path = "lua/gh-pr/actions.lua", comment_commit_oid = "abc" }, { new_tab = false }); assert(called and called.payload and called.payload.path == "lua/gh-pr/actions.lua", "Overview thread action must delegate to evolution diff"); actions.open_thread_comment_evolution_diff = original'
)

if ($WithHelpTags) {
  $nvimArgs += '+helptags doc'
}

$nvimArgs += '+qa'

& nvim @nvimArgs
if ($LASTEXITCODE -ne 0) {
  throw "Headless smoke failed with exit code $LASTEXITCODE."
}

Write-Host "Headless smoke passed." -ForegroundColor Green
